const posts = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]).filter(p => p && p.id);
if (!posts.length) return [{ json: { ok: false, action: 'skip', message: 'No published posts with metrics.' } }];
const rows = [];
for (const p of posts) {
  const avg = Number(p.account_average_views_at_check || 0);
  const mult = avg > 0 ? Number(p.views || 0) / avg : Number(p.views_multiplier || 0);
  const level = mult >= 20 ? 'extreme_x20' : mult >= 5 ? 'successful_x5' : mult >= 1 ? 'normal' : 'weak';
  const cv = p.package_assets?.content_queue?.content_variants;
  rows.push({
    content_pattern_id: cv?.content_pattern_id || null,
    pattern_recipe_id: cv?.pattern_recipe_id || null,
    published_post_id: p.id,
    variant_group: cv?.variant_group || null,
    production_mode: p.package_assets?.content_queue?.production_mode || null,
    views_multiplier: mult,
    engagement_score: (Number(p.likes || 0) + Number(p.comments || 0) * 3 + Number(p.saves || 0) * 5 + Number(p.shares || 0) * 6) / Math.max(Number(p.views || 1), 1),
    lead_score: Number(p.leads || 0),
    learning_result: level === 'extreme_x20' || level === 'successful_x5' ? 'increase_weight' : (level === 'weak' ? 'decrease_weight' : 'keep'),
    weight_delta: level === 'extreme_x20' ? 0.35 : (level === 'successful_x5' ? 0.2 : (level === 'weak' ? -0.15 : 0)),
    notes: 'Auto numeric learning: success=' + level,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });
}
const system = [
  'You are the strategy brain of a viral content factory for premium custom tables.',
  'Analyze published post metrics and convert them into precise learning notes for future pattern selection.',
  'Use x5 as successful and x20 as extreme viral. If user dislikes a video but it performs, preserve the viral mechanism and lower only brand/premium cautions.',
  'Return only valid JSON in Russian.'
].join(' ');
const user = [
  'For each learning row, write short but useful notes: what to increase/decrease, which hook/visual/scenario/audio/CTA mechanics to reuse or avoid.',
  'Also return global_recommendations for next WF02/WF03/WF03.5 decisions.',
  'Return JSON: {"row_notes":[{"published_post_id":"","notes":""}],"global_recommendations":[]}',
  'POSTS:',
  JSON.stringify(posts),
  'NUMERIC_ROWS:',
  JSON.stringify(rows)
].join('\n');
return [{ json: { ok: true, rows, polza_body: { model: 'openai/gpt-5.2', temperature: 0.2, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } }];

const source = $('Code: build learning rows').first().json;
const response = $input.first()?.json || {};
const raw = response.choices?.[0]?.message?.content || response.message?.content || response.content || '';
function parseJson(text) {
  const clean = String(text || '').trim().replace(/^\`\`\`json\s*/i, '').replace(/^\`\`\`\s*/i, '').replace(/\`\`\`$/i, '').trim();
  try { return JSON.parse(clean); } catch (e) {}
  const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(clean.slice(start, end + 1));
  return {};
}
const parsed = parseJson(raw);
const notesByPost = new Map((Array.isArray(parsed.row_notes) ? parsed.row_notes : []).map(x => [String(x.published_post_id), String(x.notes || '')]));
const global = Array.isArray(parsed.global_recommendations) ? parsed.global_recommendations : [];
const rows = (source.rows || []).map(r => ({
  ...r,
  notes: [r.notes, notesByPost.get(String(r.published_post_id)), global.length ? 'Global: ' + global.join(' | ') : ''].filter(Boolean).join(' | ').slice(0, 2000),
  updated_at: new Date().toISOString()
}));
return [{ json: { ok: true, rows, global_recommendations: global } }];

const result = {
  action: 'learning_saved',
  message: 'WF06 saved pattern performance rows.'
};
return [{ json: result }];

const result = {
  action: 'skip',
  message: 'No metrics available for WF06.'
};
return [{ json: result }];
